import{_ as a,o as n,a as p,b as e}from"./app.UgfkfLuP.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"reg矢量计算","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_vector_compute"},{"text":"数据重排","link":"/api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/data_reorder"},{"text":"gather","link":"/api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/gather"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/gather.md","filePath":"api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/gather.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1793005388000}'),c={name:"api/SIMD-API/tensor_api/reg_vector_compute/data_reorder/gather.md"};function l(t,s,o,d,r,i){return n(),p("div",null,[...s[0]||(s[0]=[e(`<div><article class="markdown-body"><h1>gather</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;tensor_api/experimental/arch/vector/gather_compute.h&quot;</code>，命名空间为<code>asc::te::experimental</code>。</p><p>根据<code>index</code>中逐元素保存的索引，从源寄存器<code>src</code>中收集元素，生成新的<a href="../reg_tensor/reg_tensor.html">reg_tensor</a>。索引以元素个数为单位，不是字节偏移。</p><p>设<code>VL_T</code>为一个矢量数据寄存器可容纳的<code>DataType</code>元素个数，计算关系为<code>dst.reg[i] = src.reg[index.reg[i] % VL_T]</code>。例如，<code>src</code>的前四个元素为<code>{10, 20, 30, 40}</code>，<code>index</code>的前四个元素为<code>{3, 1, 0, 2}</code>，则结果的前四个元素为<code>{40, 20, 10, 30}</code>。</p><p>本接口仅在AIV上生效。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">DataType</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">IndexType</span><span class="o">&gt;</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="n">DataType</span><span class="o">&gt;</span><span class="w"> </span><span class="n">gather</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="n">DataType</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">reg_tensor</span><span class="o">&lt;</span><span class="n">IndexType</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">index</span><span class="p">);</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>DataType</td><td>源操作数及返回结果的元素类型，支持的类型组合请参见<a href="#%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B">数据类型</a>。</td></tr><tr><td>IndexType</td><td>索引寄存器的元素类型，须为与DataType位宽相同的无符号整型。</td></tr></tbody></table><p><strong>表2</strong> 函数参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>src</td><td>输入</td><td>源寄存器，类型为<code>reg_tensor&lt;DataType&gt;</code>。</td></tr><tr><td>index</td><td>输入</td><td>索引寄存器，类型为<code>reg_tensor&lt;IndexType&gt;</code>，其中，<code>index.reg</code>提供逐元素索引。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><table><thead><tr><th>DataType</th><th>IndexType</th></tr></thead><tbody><tr><td>int8_t、uint8_t、hifloat8_t、fp8_e8m0_t、fp8_e5m2_t、fp8_e4m3fn_t</td><td>uint8_t</td></tr><tr><td>int16_t、uint16_t、half、bfloat16_t</td><td>uint16_t</td></tr><tr><td>int32_t、uint32_t、float</td><td>uint32_t</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>返回<code>reg_tensor&lt;DataType&gt;</code>，其<code>reg</code>保存收集后的数据，<code>mask</code>与<code>src.mask</code>相同。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>收集计算不使用<code>src.mask</code>或<code>index.mask</code>屏蔽元素。须保证被索引的源元素及参与计算的索引值已初始化；返回对象的<code>mask</code>直接继承<code>src.mask</code>。</li><li>索引超出源寄存器可容纳的元素范围时，按<code>index.reg[i] % VL_T</code>取模后访问。</li><li>在后续操作使用返回对象的<code>mask</code>前，须保证<code>src.mask</code>已初始化。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>以下代码片段在VF中调用。假设<code>src_tensor</code>的前四个元素为<code>{10, 20, 30, 40}</code>，<code>index_tensor</code>的前四个元素为<code>{3, 1, 0, 2}</code>。示例先将数据从UB搬入寄存器，再为源寄存器绑定有效掩码，最后将收集结果搬出到UB，结果的<code>mask</code>继承自<code>src.mask</code>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">SrcTensor</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">IndexTensor</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">DstTensor</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">gather_vf</span><span class="p">(</span><span class="n">SrcTensor</span><span class="w"> </span><span class="n">src_tensor</span><span class="p">,</span><span class="w"> </span><span class="n">IndexTensor</span><span class="w"> </span><span class="n">index_tensor</span><span class="p">,</span><span class="w"> </span><span class="n">DstTensor</span><span class="w"> </span><span class="n">dst_tensor</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">coord</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">src_reg</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load</span><span class="p">(</span><span class="n">src_tensor</span><span class="p">,</span><span class="w"> </span><span class="n">coord</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">index_reg</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">load</span><span class="p">(</span><span class="n">index_tensor</span><span class="p">,</span><span class="w"> </span><span class="n">coord</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// src_reg.mask决定结果中哪些位置有效；index_reg.mask不参与gather计算。</span>
<span class="w">    </span><span class="n">src_reg</span><span class="p">.</span><span class="n">with_mask</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">all_mask</span><span class="o">&lt;</span><span class="kt">uint16_t</span><span class="o">&gt;</span><span class="p">());</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">result</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">gather</span><span class="p">(</span><span class="n">src_reg</span><span class="p">,</span><span class="w"> </span><span class="n">index_reg</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">experimental</span><span class="o">::</span><span class="n">store</span><span class="p">(</span><span class="n">dst_tensor</span><span class="p">,</span><span class="w"> </span><span class="n">coord</span><span class="p">,</span><span class="w"> </span><span class="n">result</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const g=a(c,[["render",l]]);export{_ as __pageData,g as default};
